'use strict';
/* Tonfunk EMS-Lab: Inhalte (Wertstrom, Themenseiten, Rollen je Beruf, 48 Aufgaben, Begriffe). Erzeugt, nicht von Hand ändern.
   Nur öffentliche Angaben von tonfunk.de und allgemeines Fachwissen; alle Zahlen sind Lernwerte. */
(function (root) {
  const D = {"intro":"Tonfunk ist ein EMS-Dienstleister (Electronic Manufacturing Services). Kunden mit eigener Marke, sogenannte OEM, lassen ihre Elektronik bei Tonfunk entwickeln, fertigen, prüfen und in Kundenverpackung liefern. Jede Stufe gibt es auch einzeln, vom Muster bis zur Großserie. Unten siehst du den Weg einer Baugruppe in 15 Schritten.","NOTE":"Alle Zahlen in diesem Lab sind Lernwerte zum Üben, keine Betriebswerte von Tonfunk.","BN":{"egs":"Elektroniker","ige":"Industrieelektriker","im":"Industriemechaniker","tpd":"Techn. Produktdesigner","fll":"Lagerlogistik","ik":"Industriekaufmann","fi":"Fachinformatiker","tec":"Techniker Elektrotechnik","stu":"Studium Elektrotechnik","wing":"Wirtschaftsingenieur","winf":"Wirtschaftsinformatik"},"schritte":[{"id":"anf","name":"Anfrage und Angebot","kurz":"Kunde fragt an, wir kalkulieren","was":"Ein Kunde, meist ein OEM (Hersteller mit eigener Marke), schickt seine Unterlagen: Stückliste, Leiterplattendaten, Zeichnungen und die gewünschte Menge. Der Vertrieb klärt, welche Stufen gewünscht sind, von der Entwicklungsunterstützung bis zur Lieferung in Kundenverpackung. Dann wird je Baugruppe kalkuliert und ein Angebot geschrieben.","pruef":"Fehlende oder unklare Angaben werden jetzt schon beim Kunden nachgefragt. Ein Fehler, der hier auffällt, kostet fast nichts.","berufe":["ik","wing","winf","stu"]},{"id":"npi","name":"Daten prüfen und NPI","kurz":"Neues Produkt sicher anlaufen lassen","was":"NPI heißt Neuprodukt-Einführung. Fachleute prüfen Stückliste, Bestückdaten und Leiterplattenlayout darauf, ob sich alles gut fertigen und prüfen lässt. Oft wird zuerst ein Muster gebaut. Dabei entstehen Bestückprogramme, Prüfprogramme und die Prüfstrategie.","pruef":"Eine FMEA sucht vorab mögliche Fehler und legt Maßnahmen fest. Das Muster zeigt Probleme, bevor die Serie startet.","berufe":["egs","tpd","tec","stu","fi"]},{"id":"ein","name":"Einkauf","kurz":"Bauteile beschaffen, Termine sichern","was":"Der Einkauf bestellt alle Bauteile der Stückliste bei Herstellern und Händlern. Er achtet auf Preis, Lieferzeit und Mindestmengen. Knappe Bauteile (Allokation) und abgekündigte Bauteile (EOL) werden früh erkannt.","pruef":"Bestellt werden nur Bauteile, die laut Stückliste freigegeben sind. Bei Engpässen wird der Kunde früh informiert und eine Alternative mit ihm abgestimmt.","berufe":["ik","wing","fll","winf"]},{"id":"we","name":"Wareneingang","kurz":"Ware annehmen, prüfen, buchen","was":"Die Lieferung wird mit Bestellung und Lieferschein verglichen. Jede Rolle und jede Packung bekommt ein Etikett mit Barcode, Losnummer und Datum. Bei feuchteempfindlichen Bauteilen werden die MSL-Stufe und die Verpackung geprüft.","pruef":"Falsche Teile, falsche Mengen oder beschädigte Verpackungen werden hier aufgehalten. Das ist die billigste Stelle, um einen Fehler zu finden.","berufe":["fll","ik","egs"]},{"id":"lag","name":"Lager","kurz":"Trocken und ESD-geschützt lagern","was":"Bauteile liegen im Lager an festen, gebuchten Plätzen. Feuchteempfindliche Bauteile kommen in Trockenschränke oder versiegelte Beutel. Das Lager arbeitet nach FIFO: Was zuerst kam, geht zuerst raus.","pruef":"Das Lagersystem kennt jeden Platz und jedes Los. Die offene Zeit feuchteempfindlicher Bauteile wird überwacht, damit keine überlagerte Rolle in die Fertigung geht.","berufe":["fll","winf"]},{"id":"kom","name":"Kommissionieren und Rüsten","kurz":"Material bereitstellen, Feeder rüsten","was":"Für einen Auftrag wird das Material zusammengestellt, das nennt man Kommissionieren. Die Bauteilrollen werden in Feeder eingesetzt. Ein Feeder ist die Zuführung, die das Bauteil zur Bestückmaschine schiebt. Oft wird schon neben der Linie gerüstet, während noch ein anderer Auftrag läuft.","pruef":"Jede Rolle und jeder Feederplatz wird gescannt. Die Software meldet sofort, wenn eine Rolle am falschen Platz steckt.","berufe":["fll","egs","ige"]},{"id":"smt","name":"SMT-Linie (Pastendruck, SPI, Bestücken, Reflow)","kurz":"Paste drucken, bestücken, löten","was":"SMT heißt Oberflächenmontage. Zuerst wird Lotpaste durch eine Schablone gedruckt oder per Jetprint ohne Schablone aufgespritzt. Dann setzt der Bestückautomat die Bauteile auf, bis hinab zu winzigen Bauformen wie 01005 und µBGA. Im Reflow-Ofen schmilzt die Paste und verlötet alle Bauteile auf einmal, auf Wunsch unter Stickstoff.","pruef":"Direkt nach dem Druck misst die 3D-SPI jedes Pastendepot. Fehldrucke werden gereinigt, bevor teure Bauteile darauf landen.","berufe":["egs","ige","im","tec"]},{"id":"aoi","name":"AOI und Röntgen","kurz":"Lötstellen sehen und durchleuchten","was":"Die AOI (automatische optische Inspektion) fotografiert jede Baugruppe und vergleicht sie mit dem Sollbild. Die AOI findet fehlende, verdrehte oder falsche Bauteile und schlechte Lötstellen. Bei BGA und QFN liegen die Lötstellen unter dem Bauteil, darum wird dort geröntgt.","pruef":"Die AOI prüft 100 % der Baugruppen. Das Röntgenbild zeigt Brücken, offene Lötstellen und Hohlräume (Voids) unter dem Bauteil.","berufe":["egs","tec","fi"]},{"id":"tht","name":"THT und Löten","kurz":"Bedrahtete Bauteile einsetzen und löten","was":"THT heißt Durchsteckmontage: Bauteile mit Drähten stecken durch Bohrungen der Leiterplatte. Gelötet wird mit Wellenlöten, Selektivlöten (Mini-Welle) oder Tauchlöten. Steckverbinder können auch ohne Lot eingepresst werden. Einzelne Fehler werden gezielt nachgearbeitet, das heißt Rework.","pruef":"Beim Einpressen überwacht die Maschine Weg und Kraft für jeden Pin. Lötstellen werden nach IPC-A-610 beurteilt.","berufe":["egs","ige"]},{"id":"test","name":"Elektrischer Test","kurz":"Messen, programmieren, Funktion prüfen","was":"Beim ICT (In-Circuit-Test) kontaktiert ein Nadeladapter viele Messpunkte gleichzeitig und prüft Bauteile und Verbindungen. Bei kleinen und mittleren Stückzahlen fahren beim Flying-Probe bewegliche Nadeln die Punkte ohne Adapter an. Dazu kommen Boundary-Scan, das Programmieren der Bausteine und der Funktionstest.","pruef":"Hier fallen Kurzschlüsse, Unterbrechungen und falsche Bauteilwerte auf. Jedes Prüfergebnis wird zur Seriennummer gespeichert.","berufe":["egs","fi","tec","stu"]},{"id":"mon","name":"Montage","kurz":"Gerät zusammenbauen und beschriften","was":"In der Montage (High Level Assembly) werden Leiterplatten, Kabel, Mechanikteile und Gehäuse zum fertigen Gerät. Schrauben werden mit überwachten Drehmomentschraubern angezogen. Typenschild oder Code werden per Laser dauerhaft aufgebracht.","pruef":"Der Schrauber meldet jede Schraube mit falschem Drehmoment. Vorrichtungen halten die Teile in der richtigen Lage, damit nichts schief verbaut wird.","berufe":["im","ige","tpd"]},{"id":"lack","name":"Lackieren und Vergießen","kurz":"Gegen Feuchte und Vibration schützen","was":"Schutzlack wird selektiv gesprüht oder als Tauch-, Schlepp- oder Pinsellack aufgetragen. Beim Verguss wird die Baugruppe mit 1K- oder 2K-Material eingegossen, zum Beispiel Epoxid, PU oder Silikon. Dam & Fill und Underfill schützen einzelne Bauteile gezielt.","pruef":"Viele Schutzlacke leuchten unter UV-Licht, so sieht man, ob alles bedeckt ist. Stecker und Kontakte werden vorher abgedeckt und danach kontrolliert.","berufe":["im","egs"]},{"id":"frei","name":"Endprüfung und Freigabe","kurz":"Letzte Prüfung vor dem Versand","was":"Das fertige Gerät wird in der Endprüfung kontrolliert: Funktion, Aussehen und Beschriftung. Die Daten aller Stationen müssen vollständig und in Ordnung sein. Erst dann wird das Los freigegeben.","pruef":"Das MES lässt nur Geräte weiter, die alle Prüfschritte bestanden haben. Ein Fehler, der erst hier auffällt, kostet schon viel mehr als in der Fertigung.","berufe":["egs","tec","wing"]},{"id":"vers","name":"Verpacken und Versand","kurz":"Kundenverpackung und Direktversand","was":"Die Geräte werden in die Verpackung des Kunden gepackt, oft schon verkaufsfertig. Lieferschein und Etiketten werden erstellt. Auf Wunsch geht die Ware direkt an den Kunden des Kunden.","pruef":"Beim Packen wird jede Seriennummer gescannt, so ist klar, welches Gerät in welchem Karton steckt. Der ESD-Schutz gilt bis zum Schluss.","berufe":["fll","ik"]},{"id":"rech","name":"Rechnung und Nachbetreuung","kurz":"Abrechnen und Kunden weiter begleiten","was":"Nach der Lieferung wird die Rechnung geschrieben. Rückfragen und Reklamationen des Kunden werden bearbeitet. Das Obsoleszenz-Management beobachtet, ob Bauteile abgekündigt werden, damit das Produkt lange lieferbar bleibt.","pruef":"Reklamationen werden mit der 8D-Methode bearbeitet, bis die Ursache abgestellt ist. Was man dabei lernt, fließt zurück in FMEA und Fertigung.","berufe":["ik","winf","wing"]}],"seiten":{"fer":[{"h":"SMT: Bauteile auf der Oberfläche","t":"Bei SMT sitzen die Bauteile direkt auf der Oberfläche der Leiterplatte, ohne Bohrungen. Die Lotpaste wird meist durch eine Schablone aus dünnem Metall gedruckt. Gestufte Schablonen sind an manchen Stellen dicker oder dünner, so bekommt jedes Bauteil die passende Pastenmenge. Beim Jetprint spritzt eine Düse die Paste ganz ohne Schablone auf, praktisch für Muster und für Sonderstellen. Danach bestückt der Automat und der Reflow-Ofen lötet. Tonfunk verarbeitet starre, starrflexible und flexible Leiterplatten."},{"h":"Reflow und Stickstoff","t":"Im Reflow-Ofen fährt die Baugruppe durch mehrere Zonen: vorwärmen, aufschmelzen, abkühlen. Dieser Temperaturverlauf heißt Profil und muss zu Paste und Bauteilen passen. Zu heiß schadet den Bauteilen, zu kalt gibt schlechte Lötstellen. Unter Stickstoff ist kaum Sauerstoff im Ofen, darum oxidiert das Lot weniger und benetzt besser. Benetzen heißt: Das flüssige Lot fließt sauber auf die Metallfläche."},{"h":"THT: Welle, Selektiv, Tauchen","t":"Beim Wellenlöten fährt die Unterseite der Leiterplatte über eine Welle aus flüssigem Lot. Das ist schnell, aber Bereiche, die kein Lot abbekommen dürfen, müssen geschützt werden. Selektivlöten lötet mit einer Mini-Welle nur einzelne Stellen, ideal wenn schon viele SMD-Bauteile auf der Platine sitzen. Beim Tauchlöten wird die Lötseite kurz in ein Lotbad getaucht. Einpressen verbindet Steckerpins ganz ohne Lot."},{"h":"Bleifrei und bleihaltig","t":"Nach der RoHS-Richtlinie ist Blei in den meisten Elektronikprodukten verboten. Bleifreies Lot schmilzt heißer, das belastet die Bauteile stärker. Für Anwendungen mit Ausnahmeregel wird noch bleihaltig gelötet. Beide Lote dürfen nicht vermischt werden, darum sind Werkzeuge, Lot und Aufträge klar gekennzeichnet."},{"h":"Lack und Verguss","t":"Schutzlack ist eine dünne Schicht gegen Feuchte, Staub und Betauung. Er wird selektiv gesprüht oder als Tauch-, Schlepp- oder Pinsellack aufgetragen. Beim Verguss wird die ganze Baugruppe in Epoxid, PU oder Silikon eingegossen, als 1K-Material (eine Komponente) oder 2K-Material (zwei Komponenten werden gemischt). Dam & Fill baut erst einen Damm und füllt dann die Fläche darin. Underfill fließt unter große Bauteile wie BGA und stärkt die Lötstellen gegen Biegen und Vibration."},{"h":"Nacharbeit (Rework)","t":"Nicht jeder Fehler heißt Ausschuss. Beim Reflow-Rework wird ein einzelnes Bauteil gezielt erhitzt, entfernt und neu eingelötet, auch ein BGA. Das braucht ein passendes Temperaturprofil, damit die Nachbarn nicht leiden. Nach der Nacharbeit wird die Stelle erneut geprüft, zum Beispiel mit Röntgen."}],"pru":[{"h":"SPI: die Paste messen","t":"SPI heißt Lotpasteninspektion. Direkt nach dem Druck misst eine 3D-Kamera jedes Pastendepot: Höhe, Fläche, Volumen und Versatz. Zu wenig Paste gibt offene Lötstellen, zu viel gibt Brücken. Ein Fehldruck lässt sich noch abwaschen, bevor Bauteile darauf sitzen. Tonfunk prüft so 100 % der Baugruppen."},{"h":"AOI und Röntgen","t":"Die AOI vergleicht Kamerabilder jeder Baugruppe mit dem Sollzustand. Die AOI erkennt fehlende, verdrehte, versetzte und falsche Bauteile sowie sichtbare Lötfehler. Bei BGA und QFN liegen die Lötstellen unter dem Gehäuse, die Kamera sieht sie nicht. Dort zeigt das Röntgenbild Brücken, offene Stellen und Voids, also Gasblasen im Lot."},{"h":"ICT und Boundary-Scan","t":"Beim ICT drückt ein Nadeladapter auf viele Prüfpunkte gleichzeitig. Das Prüfgerät misst Widerstände, Kondensatoren, Dioden und sucht Kurzschlüsse und Unterbrechungen. Der Test dauert nur kurz, aber der Adapter muss erst gebaut werden, bei Tonfunk im eigenen Prüfmittelbau. Am ICT kann man auch Bausteine programmieren. Boundary-Scan prüft Verbindungen über eine eingebaute Testschnittstelle der Chips, auch dort, wo keine Nadel hinkommt."},{"h":"Flying-Probe","t":"Beim Flying-Probe fahren wenige bewegliche Nadeln die Prüfpunkte nacheinander an. Es braucht keinen Adapter, nur ein Prüfprogramm. Dafür dauert der Test je Baugruppe länger. Darum passt Flying-Probe gut für Muster, kleine und mittlere Stückzahlen."},{"h":"Funktionstest","t":"Der Funktionstest prüft, ob die Baugruppe das tut, was sie soll. Die Baugruppe bekommt Spannung und Signale, und man misst die Antwort. Die Prüfvorschrift kommt meist vom Kunden. Oft wird dabei auch die Software aufgespielt und die Seriennummer gespeichert."},{"h":"Prüfstrategie nach Stückzahl","t":"Welche Prüfung sich lohnt, hängt von der Stückzahl ab. ICT hat hohe Einmalkosten für den Adapter, aber kleine Kosten je Stück. Flying-Probe hat keine Einmalkosten, aber höhere Kosten je Stück. Ab einer bestimmten Stückzahl, dem Gleichstand, wird ICT günstiger: n = Adapterpreis / (Flying-Probe je Stück minus ICT je Stück)."}],"mat":[{"h":"Bauteilrollen und Feeder","t":"SMD-Bauteile kommen meist auf Rollen, in einem Gurt mit kleinen Taschen. Eine Rolle fasst je nach Bauform hunderte bis tausende Bauteile. Der Feeder ist die Zuführung an der Bestückmaschine: Er zieht den Gurt Tasche für Tasche weiter. Beim Rüsten werden Rollen in Feeder gesetzt und der Platz per Scan bestätigt."},{"h":"MSL und Bodenlebensdauer","t":"Viele Bauteile nehmen Feuchte aus der Luft auf. Beim Löten verdampft diese Feuchte schlagartig, das Gehäuse kann reißen. Die Norm J-STD-020 teilt Bauteile darum in Feuchteklassen (MSL) ein, J-STD-033 regelt Lagerung, Bodenlebensdauer und Backen. Die Bodenlebensdauer gilt bei höchstens 30 °C und 60 % relativer Feuchte: MSL 2 ein Jahr, MSL 2a vier Wochen, MSL 3 168 h, MSL 4 72 h, MSL 5 48 h, MSL 5a 24 h. MSL 1 ist bis 30 °C und 85 % rF unbegrenzt haltbar. MSL 6 muss vor jedem Gebrauch gebacken und dann innerhalb der Zeit auf dem Etikett gelötet werden."},{"h":"Trocken lagern und backen","t":"Feuchteempfindliche Bauteile kommen in einen Trockenbeutel mit Trockenmittel und Feuchteindikator oder in einen Trockenschrank. Die Zeit außerhalb wird mitgeschrieben. Ist die Bodenlebensdauer abgelaufen, werden die Bauteile nach Vorgabe der Norm gebacken. Danach beginnt die Bodenlebensdauer neu."},{"h":"ESD-Verpackung","t":"ESD heißt elektrostatische Entladung, ein kleiner Funke kann einen Chip zerstören, ohne dass man es spürt. Gearbeitet wird darum in einer EPA, einem geschützten Bereich nach DIN EN 61340-5-1. Ein ESD-Schutzbeutel ist innen ableitfähig, damit sich am Bauteil keine Ladung aufbaut. Eine dünne Metallschicht im Beutel schirmt Ladungen und Felder von außen ab."},{"h":"FIFO und Losnummer","t":"FIFO heißt First In, First Out: Was zuerst ins Lager kam, wird zuerst verbraucht. So altert nichts im Regal. Jede Rolle trägt eine Losnummer, also die Nummer der Fertigungscharge beim Hersteller. Über diese Nummer weiß man später, in welchen Geräten genau dieses Los steckt."}],"qua":[{"h":"ISO 9001 und ISO 14001","t":"ISO 9001 ist die Grundnorm für Qualitätsmanagement. Die Norm verlangt klare Abläufe, Verantwortungen und ständige Verbesserung. ISO 14001 regelt das Umweltmanagement: Energie, Abfall und Stoffe werden geplant und verbessert. Tonfunk ist nach beiden zertifiziert."},{"h":"IATF 16949 und ISO 13485","t":"IATF 16949 baut auf ISO 9001 auf und gilt für die Automobilindustrie. Die Norm fordert zum Beispiel FMEA, Rückverfolgung und strenge Freigaben. ISO 13485 ist die Qualitätsnorm für Medizinprodukte. Dort zählen lückenlose Dokumentation und Risikobetrachtung besonders viel."},{"h":"IPC-A-610: drei Klassen","t":"IPC-A-610 beschreibt mit Bildern, wann eine bestückte Baugruppe annehmbar ist. Klasse 1 gilt für allgemeine Elektronik. Klasse 2 gilt für Geräte, die lange und zuverlässig laufen sollen. Klasse 3 gilt für hohe Zuverlässigkeit, bei der ein Ausfall nicht passieren darf, zum Beispiel in lebenserhaltender Medizintechnik. Je höher die Klasse, desto strenger die Grenzen."},{"h":"FMEA","t":"FMEA heißt Fehlermöglichkeits- und Einflussanalyse. Das Team fragt vor der Fertigung: Was kann schiefgehen, wie schlimm wäre es, wie oft passiert es und würden wir es entdecken? Für die größten Risiken werden Maßnahmen festgelegt. Bei Tonfunk startet das CAQ-System schon mit der FMEA."},{"h":"8D-Methode","t":"Bei einer Reklamation hilft der 8D-Bericht mit acht Schritten. Ein Team wird gebildet, das Problem beschrieben und sofort eingedämmt, damit kein weiteres fehlerhaftes Teil zum Kunden geht. Dann wird die Ursache gesucht, abgestellt und die Wirkung geprüft. Zum Schluss wird verhindert, dass der Fehler woanders wieder auftritt, und das Team gewürdigt."},{"h":"Zehnerregel","t":"Je später ein Fehler gefunden wird, desto teurer wird er, pro Stufe etwa zehnmal. Zum Beispiel: 0,10 € im Wareneingang, 1 € in der Fertigung, 10 € in der Endprüfung, 100 € beim Kunden. Darum lohnt sich Prüfen früh im Wertstrom. Dazu passt das Motto: Es gibt immer eine Lösung, am besten schon ganz vorn."}],"dat":[{"h":"Barcode je Leiterplatte","t":"Jede Leiterplatte bekommt gleich zu Beginn einen eigenen Code, oft als kleinen Datamatrix-Code. Jede Station liest ihn und weiß, welches Teil gerade vor ihr liegt. So wird jede Bearbeitung genau dieser Baugruppe zugeordnet."},{"h":"Seriennummer","t":"Die Seriennummer ist der eindeutige Name eines einzelnen Geräts. Die Seriennummer wird mit den Codes aller verbauten Leiterplatten verknüpft. Steht sie auf dem Typenschild, kann man auch Jahre später alle Daten des Geräts finden."},{"h":"MES","t":"MES heißt Manufacturing Execution System, die Software für die Steuerung der Fertigung. Es weiß, welcher Auftrag wo läuft, und speichert jeden Schritt. Es kann ein Teil sperren, wenn ein Prüfschritt fehlt oder nicht bestanden wurde. So gelangt keine ungeprüfte Baugruppe weiter."},{"h":"Stückliste (BOM)","t":"Die Stückliste, englisch BOM (Bill of Materials), listet jedes Bauteil mit Teilenummer, Menge und Bestückposition. Aus ihr werden Einkauf, Lager und Bestückprogramm abgeleitet. Ein Fehler in der Stückliste wandert durch den ganzen Wertstrom, darum wird sie in der NPI genau geprüft."},{"h":"Bauteillos mit Gerät verknüpft","t":"Beim Rüsten wird jede Rolle mit ihrer Losnummer gescannt. Die Datenbank merkt sich, welches Los in welchem Zeitraum auf welcher Baugruppe gelandet ist. Meldet ein Hersteller ein fehlerhaftes Los, findet man sofort die betroffenen Geräte. Tonfunk verfolgt so bis zum einzelnen Gerät zurück."},{"h":"Prüfdaten","t":"SPI, AOI, Röntgen, ICT und Funktionstest liefern Messwerte und Bilder. Diese werden zur Seriennummer gespeichert. Häufen sich Fehler an einer Stelle, sieht man es in der Auswertung früh und kann gegensteuern."}],"mec":[{"h":"Drehmoment","t":"Das Drehmoment sagt, wie fest eine Schraube angezogen wird. Es gilt M = F × r, also Kraft mal Hebelarm, Einheit Nm. Zu locker lockert sich die Schraube, zu fest kann Gewinde oder Leiterplatte beschädigt werden. Überwachte Schrauber messen und speichern jeden Wert."},{"h":"Einpressen","t":"Beim Einpressen wird ein Pin mit leichtem Übermaß in eine Bohrung gedrückt, die Verbindung hält ohne Lot. Die Presse misst dabei Weg und Kraft. Passt die Kurve nicht, ist der Pin zum Beispiel verbogen oder die Bohrung falsch. Das Teil wird dann sofort aussortiert."},{"h":"Laserbeschriftung","t":"Ein Laser schreibt Text, Logos und Codes direkt in die Oberfläche von Gehäuse oder Leiterplatte. Die Schrift ist dauerhaft und kann nicht abfallen wie ein Etikett. Jedes Gerät kann so seine eigene Seriennummer bekommen."},{"h":"Gehäuse aus Metall und Kunststoff","t":"Zum Gerät gehört oft ein Gehäuse. Tonfunk konstruiert in 3D und liefert Stanz-, Biege-, Fräs- und Drehteile sowie Kunststoffgehäuse. Wichtig ist, dass Leiterplatte, Stecker und Gehäuse von Anfang an zusammen geplant werden. So passt am Ende alles ohne Nacharbeit."},{"h":"Toleranzen und Bohrbilder","t":"Kein Teil wird exakt auf das Maß gefertigt, jedes Maß hat eine Toleranz. Das Bohrbild ist die Lage aller Befestigungslöcher. Die Löcher der Leiterplatte und die Dome oder Gewinde im Gehäuse müssen auch bei ungünstigen Toleranzen noch zusammenpassen. Darum rechnet man die Toleranzkette durch und gibt etwas Spiel."},{"h":"Vorrichtungen","t":"Eine Vorrichtung hält Teile beim Montieren, Löten, Lackieren oder Prüfen in genau der richtigen Lage. Das macht die Arbeit schneller und verhindert falsches Einlegen. Vorrichtungen und Prüfadapter baut Tonfunk im eigenen Prüfmittelbau."}],"kun":[{"h":"Anfrage und Angebot","t":"Ein OEM fragt mit Stückliste, Daten und Menge an. Er kann den ganzen Weg bestellen oder nur einzelne Stufen, vom Muster bis zur Großserie. Aus den Daten wird je Baugruppe kalkuliert. Das Angebot nennt Preis, Liefertermin und offene Fragen."},{"h":"Kalkulation je Baugruppe","t":"Die Kosten je Baugruppe setzen sich zusammen aus Material, Bestückpunkten mal Preis je Punkt, THT-Lötstellen mal Preis je Lötstelle, Prüfzeit mal Minutensatz und den Rüstkosten geteilt durch die Losgröße. Auf diese Kosten kommt ein Zuschlag: Angebot = Kosten × (1 + Zuschlag). Wer die Bausteine kennt, versteht, warum zwei ähnliche Baugruppen unterschiedlich viel kosten."},{"h":"Losgröße und Rüstkosten","t":"Rüsten kostet Zeit und Geld, egal ob danach 10 oder 1000 Stück laufen. Bei kleinen Losen verteilen sich die Rüstkosten auf wenige Teile, jedes Teil wird teurer. Große Lose sind je Stück günstiger, binden aber Geld im Lager. Die richtige Losgröße ist ein Kompromiss."},{"h":"Obsoleszenz, EOL, Last Time Buy","t":"Obsoleszenz heißt: Ein Bauteil wird nicht mehr hergestellt. Der Hersteller kündigt das mit einer EOL-Meldung (End of Life) an. Bis zu einem Stichtag ist eine letzte Bestellung möglich, der Last Time Buy. Danach braucht man Restbestände oder ein Ersatzbauteil, oft mit Änderung der Leiterplatte."},{"h":"Allokation und Liefertermin","t":"Bei Allokation ist ein Bauteil knapp, und die Hersteller teilen die Mengen zu. Lieferzeiten können dann sehr lang werden. Ein früher Blick auf kritische Bauteile schützt den Liefertermin. Der Kunde wird informiert, bevor es eng wird, nicht danach."},{"h":"Mehr als erwartet","t":"Ein guter EMS-Partner liefert nicht nur, was bestellt ist. Er meldet zum Beispiel ein bald abgekündigtes Bauteil, schlägt eine günstigere Prüfstrategie vor oder macht die Baugruppe besser fertigbar. Das passt zu Werten wie Partnerschaft, Vertrauen und Kommunikation. Und zum Motto: Es gibt immer eine Lösung."}]},"beruf":{"egs":{"rolle":"Als Elektroniker für Geräte und Systeme kennst du die Baugruppe von innen. Du richtest Linien und Prüfplätze ein, suchst Fehler mit AOI, Röntgen und Messgerät und reparierst Baugruppen. Bei neuen Produkten hilfst du, Prüfprogramme und Musterbau zum Laufen zu bringen.","schritte":["npi","we","kom","smt","aoi","tht","test","lack","frei"]},"ige":{"rolle":"Als Industrieelektriker hältst du Maschinen und Anlagen elektrisch am Laufen. Du rüstest, bedienst und überwachst Linien und Lötanlagen. Bei Störungen findest du die Ursache und schaltest sicher frei.","schritte":["kom","smt","tht","mon"]},"im":{"rolle":"Als Industriemechaniker sorgst du dafür, dass Bestückautomaten, Öfen, Pressen und Dosieranlagen mechanisch sauber laufen. Du wartest, stellst ein und tauschst Verschleißteile. In der Montage achtest du auf Drehmoment, Passungen und Vorrichtungen.","schritte":["smt","mon","lack"]},"tpd":{"rolle":"Als Technischer Produktdesigner konstruierst du in 3D Gehäuse, Blechteile und Vorrichtungen. Du prüfst, ob Leiterplatte, Bohrbild und Gehäuse mit allen Toleranzen zusammenpassen. Deine Zeichnungen sind die Grundlage für Fertigung und Montage.","schritte":["npi","mon"]},"fll":{"rolle":"Als Fachkraft für Lagerlogistik nimmst du Bauteile an, prüfst und buchst sie. Du lagerst sie ESD-gerecht und trocken, achtest auf FIFO und MSL und stellst das Material für die Linie bereit. Am Ende verpackst du die Geräte und machst den Versand fertig.","schritte":["ein","we","lag","kom","vers"]},"ik":{"rolle":"Als Industriekaufmann bearbeitest du Anfragen, rechnest Angebote mit und bestellst Bauteile. Du hältst Kontakt zu Kunden und Lieferanten, gerade wenn Bauteile knapp oder abgekündigt sind. Am Ende schreibst du Rechnungen und klärst kaufmännische Fragen.","schritte":["anf","ein","we","vers","rech"]},"fi":{"rolle":"Als Fachinformatiker betreust du die Software hinter der Fertigung: MES, Datenbanken, Prüfprogramme und Schnittstellen. Du sorgst dafür, dass jeder Scan und jedes Prüfergebnis richtig gespeichert wird. Beim Programmieren der Bausteine und beim Auswerten von Prüfdaten bist du gefragt.","schritte":["npi","aoi","test"]},"tec":{"rolle":"Als Techniker für Elektrotechnik planst und verbesserst du Prozesse. Du legst Prüfstrategien fest, optimierst Lötprofile und Prüfprogramme und wertest Fehler aus. Bei neuen Produkten begleitest du die NPI bis zur Serienfreigabe.","schritte":["npi","smt","aoi","test","frei"]},"stu":{"rolle":"Im Studium Elektrotechnik lernst du bei einem EMS-Fertiger, wie aus einer Entwicklung ein fertigbares und prüfbares Produkt wird. Du unterstützt bei Machbarkeit, Prüfkonzept und Messtechnik. Projekte und Abschlussarbeiten können genau hier ansetzen.","schritte":["anf","npi","test"]},"wing":{"rolle":"Als Wirtschaftsingenieur verbindest du Technik und Kosten. Du kalkulierst Baugruppen, vergleichst Prüfstrategien nach Stückzahl und planst Losgrößen. Du achtest auf Liefertermine, Ausbeute und Fehlerkosten.","schritte":["anf","ein","frei","rech"]},"winf":{"rolle":"Als Wirtschaftsinformatiker verbindest du Geschäftsprozesse und IT. Du arbeitest an Systemen für Angebote, Einkauf, Lager und Rechnung und sorgst dafür, dass die Daten zusammenpassen. Auswertungen aus diesen Daten helfen bei Entscheidungen.","schritte":["anf","ein","lag","rech"]}},"tasks":[{"id":"ems1","cat":"Wertstrom","title":"Was ist ein EMS-Fertiger?","level":1,"kind":"mc","text":"Eine Freundin fragt dich, was Tonfunk eigentlich macht. Welche Antwort passt am besten zu einem EMS-Dienstleister?","choices":["Tonfunk entwickelt und verkauft eigene Geräte unter eigener Marke im Handel.","Tonfunk fertigt Elektronik im Auftrag für Hersteller mit eigener Marke (OEM).","Tonfunk handelt nur mit Bauteilen und liefert sie an Werkstätten.","Tonfunk repariert defekte Geräte von Privatkunden."],"correct":1,"tips":["EMS steht für Electronic Manufacturing Services.","Services heißt Dienstleistung: Jemand anderes gibt den Auftrag.","Der Auftraggeber verkauft das Gerät später unter seiner eigenen Marke."],"expl":"EMS heißt Fertigung von Elektronik als Dienstleistung im Auftrag. Der Kunde ist ein OEM, der das Gerät unter seiner Marke verkauft. Eigene Marke, reiner Bauteilhandel oder Privatreparatur sind andere Geschäftsmodelle."},{"id":"ems2","cat":"Wertstrom","title":"Wohin nach dem Wareneingang?","level":1,"kind":"mc","text":"Eine Lieferung Bauteilrollen ist im Wareneingang geprüft, etikettiert und gebucht. Der Auftrag dafür startet erst nächste Woche. Wohin gehen die Rollen jetzt?","choices":["Direkt an die SMT-Linie, damit sie schon bereitliegen.","Zurück an den Lieferanten zur Sicherheit.","Ins Lager, an einen gebuchten Platz, trocken und ESD-geschützt.","In die Endprüfung."],"correct":2,"tips":["Denk an die Reihenfolge im Wertstrom.","Bis zum Auftrag müssen die Bauteile sicher aufbewahrt werden.","Feuchte und Entladungen schaden den Bauteilen, wo bewahrt man sie geschützt auf?"],"expl":"Nach dem Wareneingang kommt das Lager, erst zum Auftrag wird kommissioniert und gerüstet. An der Linie würden die Rollen nur Platz belegen und eventuell Feuchte ziehen. Rücksendung und Endprüfung passen hier nicht."},{"id":"ems3","cat":"Wertstrom","title":"Warum Daten vorab prüfen?","level":2,"kind":"mc","text":"Ein neues Produkt kommt zu Tonfunk. Bevor die Serie startet, werden in der NPI Stückliste, Bestückdaten und Layout genau geprüft. Was ist der wichtigste Grund?","choices":["Fehler und Unklarheiten finden, solange sie noch fast nichts kosten.","Damit der Kunde länger auf sein Angebot warten muss.","Weil die Bestückmaschine ohne Prüfung keine Daten annimmt.","Damit man die Stückliste nicht mehr braucht."],"correct":0,"tips":["Denk an die Zehnerregel der Fehlerkosten.","Was kostet ein Fehler auf dem Papier und was in der fertigen Serie?","Früh gefunden ist billig gefunden."],"expl":"Ein Fehler in den Daten kostet vor der Serie fast nichts, in der Serie oder beim Kunden sehr viel. Die Prüfung verzögert nicht absichtlich, und die Stückliste bleibt die Grundlage für alles. Maschinen nehmen auch fehlerhafte Daten an, genau das ist die Gefahr."},{"id":"ems4","cat":"Wertstrom","title":"Was gehört zur SMT-Linie?","level":2,"kind":"mc","text":"Welche Arbeitsschritte gehören zur SMT-Linie? Wähle alle richtigen.","choices":["Wellenlöten der bedrahteten Bauteile","Pastendruck mit anschließender SPI","Verpacken in Kundenverpackung","Reflow-Löten"],"correct":[1,3],"tips":["SMT heißt Oberflächenmontage.","Auf der SMT-Linie wird gedruckt, gemessen, bestückt und gelötet.","Die Welle ist für THT, Verpacken kommt ganz am Ende."],"expl":"Die SMT-Linie besteht aus Pastendruck, SPI, Bestücken und Reflow. Wellenlöten gehört zu THT, das Verpacken ist der vorletzte Schritt im Wertstrom."},{"id":"ems5","cat":"Wertstrom","title":"Nur einzelne Stufen","level":3,"kind":"mc","text":"Ein Kunde hat seine Baugruppen schon bestückt und geprüft. Er möchte bei Tonfunk nur Vergießen, Endprüfung und Verpacken in seine Kundenverpackung. Was ist richtig?","choices":["Das geht nicht, ein EMS-Fertiger übernimmt immer den ganzen Wertstrom.","Das geht nur, wenn Tonfunk die Baugruppen vorher neu bestückt.","Das geht nur bei Großserien.","Das geht, jede Stufe des Wertstroms kann auch einzeln beauftragt werden."],"correct":3,"tips":["Denk an das Leistungsangebot von Tonfunk.","Vom Einzelstück bis zur Großserie, von Entwicklungsunterstützung bis Versand.","Der Kunde kann aussuchen, welche Teile er braucht."],"expl":"Tonfunk bietet jede Stufe auch einzeln an, vom Muster bis zur Großserie. Ein Zwang zum ganzen Wertstrom oder zur Neubestückung besteht nicht. Wichtig ist nur, dass Übergabe und Daten klar geregelt sind."},{"id":"ems6","cat":"Wertstrom","title":"Prüfen über den Wertstrom","level":2,"kind":"mc","text":"An welcher Stelle wird die Lotpaste auf jeder Baugruppe gemessen, bevor die Bauteile gesetzt werden?","choices":["In der AOI nach dem Reflow","In der SPI direkt nach dem Pastendruck","Im Funktionstest","Im Wareneingang"],"correct":1,"tips":["Es geht um die Paste, nicht um die Bauteile.","Die Messung muss vor dem Bestücken liegen.","Die Abkürzung enthält das P von Paste."],"expl":"Die SPI misst jedes Pastendepot direkt nach dem Druck. Die AOI kommt erst nach dem Löten, der Funktionstest noch später. Im Wareneingang gibt es noch keine gedruckte Paste."},{"id":"ems7","cat":"Fertigung","title":"Aufgabe des Reflow-Ofens","level":1,"kind":"mc","text":"Die Baugruppe ist bedruckt und bestückt. Was passiert im Reflow-Ofen?","choices":["Die Leiterplatte wird lackiert.","Die Bauteile werden von unten über eine Lotwelle gelötet.","Die Lotpaste schmilzt und verlötet alle SMD-Bauteile auf einmal.","Die Baugruppe wird getrocknet, damit Feuchte entweicht."],"correct":2,"tips":["Reflow kommt von wieder fließen.","Die Paste enthält kleine Lotkugeln.","Wärme lässt das Lot schmelzen."],"expl":"Im Reflow-Ofen schmilzt die Lotpaste, beim Abkühlen entstehen alle SMD-Lötstellen gleichzeitig. Die Lotwelle gehört zum Wellenlöten, Lack kommt später. Trocknen ist Aufgabe des Backofens, und zwar vor dem Löten, nicht im Reflow."},{"id":"ems8","cat":"Fertigung","title":"Wenige THT-Stellen löten","level":1,"kind":"mc","text":"Auf einer Baugruppe sitzen schon viele SMD-Bauteile auf beiden Seiten. Nur drei Steckverbinder mit Drähten müssen noch gelötet werden. Welches Verfahren passt am besten?","choices":["Selektivlöten mit Mini-Welle","Wellenlöten über die ganze Unterseite","Noch einmal durch den Reflow-Ofen","Verguss mit Epoxid"],"correct":0,"tips":["Die SMD-Bauteile unten sollen nicht noch einmal durchs Lot.","Gesucht ist ein Verfahren, das nur einzelne Stellen lötet.","Selektiv heißt ausgewählt."],"expl":"Selektivlöten lötet mit einer Mini-Welle nur die gewünschten Stellen. Die große Welle würde die ganze Unterseite benetzen, ein weiterer Reflow lötet normale THT-Teile nicht zuverlässig. Verguss ist keine Lötverbindung."},{"id":"ems9","cat":"Fertigung","title":"Warum Stickstoff?","level":2,"kind":"mc","text":"Ein Auftrag wird unter Stickstoff gelötet. Welchen Vorteil bringt das?","choices":["Das Lot schmilzt dadurch bei viel niedrigerer Temperatur.","Es ist weniger Sauerstoff da, das Lot oxidiert weniger und benetzt besser.","Die Bauteile werden dabei automatisch gegen ESD geschützt.","Man braucht keine Lotpaste mehr."],"correct":1,"tips":["Stickstoff verdrängt etwas aus der Luft.","Was lässt heißes Metall anlaufen?","Ohne Sauerstoff weniger Oxid."],"expl":"Stickstoff verdrängt den Sauerstoff, das flüssige Lot oxidiert weniger und fließt besser auf die Flächen. Der Schmelzpunkt bleibt gleich, ESD-Schutz und Lotpaste haben damit nichts zu tun."},{"id":"ems10","cat":"Fertigung","title":"First Pass Yield der Linie","level":2,"kind":"num","text":"Eine SMT-Linie hat drei Stufen. Ohne Nacharbeit sind gut: Druck 98 %, Bestücken 99 %, Löten 97 %. Wie groß ist der First Pass Yield der ganzen Linie in Prozent? Runde auf zwei Nachkommastellen.","answer":94.11,"tol":0.002,"unit":"%","tips":["Der FPY der Linie ist das Produkt der Ausbeuten aller Stufen.","Rechne mit Dezimalzahlen: 0,98, 0,99 und 0,97.","0,98 × 0,99 = 0,9702, das jetzt noch mal 0,97."],"steps":["FPY = 0,98 × 0,99 × 0,97","0,98 × 0,99 = 0,9702; 0,9702 × 0,97 = 0,941094","FPY ≈ 94,11 %"],"expl":"Jede Stufe frisst etwas Ausbeute, darum ist der FPY der Linie immer kleiner als die schlechteste Einzelstufe."},{"id":"ems11","cat":"Fertigung","title":"Gutteile im Los","level":3,"kind":"num","text":"Ein Los hat 1000 Baugruppen. Die SMT-Fertigung hat eine Ausbeute von 98 %, die THT-Fertigung von 95 %. Wie viele Baugruppen kommen ohne Nacharbeit gut durch beide Stufen?","answer":931,"tol":0.002,"unit":"Stück","tips":["Erst den FPY beider Stufen ausrechnen.","FPY = 0,98 × 0,95.","Gutteile = Losgröße × FPY."],"steps":["FPY = 0,98 × 0,95 = 0,931","Gutteile = 1000 × 0,931","Gutteile = 931 Stück"],"expl":"Gutteile = Losgröße × FPY, alles andere muss nachgearbeitet oder aussortiert werden."},{"id":"ems12","cat":"Fertigung","title":"BGA gegen Vibration","level":2,"kind":"mc","text":"Ein Gerät wird später starken Vibrationen ausgesetzt. Die Lötstellen unter einem großen BGA sollen gezielt mechanisch gestärkt werden. Was setzt man ein?","choices":["Selektiven Sprühlack auf die Oberseite","Tauchlack über die ganze Baugruppe","Underfill, das unter das Bauteil fließt und aushärtet","Mehr Lotpaste beim Druck"],"correct":2,"tips":["Die Lötstellen liegen unter dem Bauteil.","Gesucht ist ein Material, das den Spalt unter dem Bauteil füllt.","Under heißt unter, fill heißt füllen."],"expl":"Underfill füllt den Spalt unter dem BGA und verteilt die Kräfte, die Lötstellen werden entlastet. Schutzlacke schützen vor Feuchte, nicht vor Biegung. Mehr Paste kann sogar Brücken erzeugen."},{"id":"ems13","cat":"Prüfen","title":"Was misst die SPI?","level":1,"kind":"mc","text":"Direkt nach dem Pastendruck läuft jede Baugruppe durch die 3D-SPI. Was misst sie?","choices":["Ob die Bauteile richtig herum sitzen","Höhe, Fläche, Volumen und Lage jedes Lotpastendepots","Die elektrischen Werte der Widerstände","Die Funktion der fertigen Schaltung"],"correct":1,"tips":["Zu diesem Zeitpunkt sitzen noch keine Bauteile auf der Platine.","SPI heißt Solder Paste Inspection.","Gemessen wird die Paste in drei Dimensionen."],"expl":"Die SPI misst die gedruckte Lotpaste dreidimensional. Bauteillage prüft die AOI, Werte misst der ICT, die Funktion der Funktionstest."},{"id":"ems14","cat":"Prüfen","title":"Warum Röntgen bei BGA?","level":1,"kind":"mc","text":"Die AOI meldet bei einem BGA keinen Fehler. Trotzdem wird die Baugruppe geröntgt. Warum?","choices":["Weil die Lötstellen eines BGA unter dem Gehäuse liegen und die Kamera sie nicht sieht.","Weil Röntgen die Lötstellen nachträglich verbessert.","Weil die AOI bei BGA grundsätzlich falsche Fehler meldet.","Weil der Kunde sonst die Seriennummer nicht lesen kann."],"correct":0,"tips":["Wo sitzen die Lotkugeln eines BGA?","Eine Kamera sieht nur, was von oben sichtbar ist.","Röntgen kann durch das Bauteil hindurchsehen."],"expl":"Die Lötkugeln eines BGA liegen verdeckt unter dem Bauteil, nur Röntgen zeigt Brücken, offene Stellen und Voids. Röntgen repariert nichts, und die AOI arbeitet bei sichtbaren Merkmalen zuverlässig."},{"id":"ems15","cat":"Prüfen","title":"ICT-Kosten gesamt","level":2,"kind":"num","text":"Für eine Serie von 3000 Baugruppen baut der Prüfmittelbau einen ICT-Adapter für 8000 €. Der Test kostet danach 0,40 € je Baugruppe. Wie hoch sind die ICT-Prüfkosten insgesamt?","answer":9200,"tol":0.002,"unit":"€","tips":["Gesamtkosten ICT = Adapterpreis + Stückzahl × Kosten je Stück.","Rechne zuerst die Testkosten für alle 3000 Stück.","3000 × 0,40 € = 1200 €."],"steps":["Testkosten = 3000 × 0,40 € = 1200 €","Gesamt ICT = 8000 € + 1200 €","Gesamt ICT = 9200 €"],"expl":"Beim ICT dominiert bei kleinen Mengen der Adapter, bei großen Mengen sind die Kosten je Stück winzig."},{"id":"ems16","cat":"Prüfen","title":"Flying-Probe für Muster","level":1,"kind":"num","text":"Ein Musterauftrag hat 300 Baugruppen. Der Flying-Probe-Test kostet 4,00 € je Baugruppe, ein Adapter wird nicht gebraucht. Wie hoch sind die Prüfkosten insgesamt?","answer":1200,"tol":0.002,"unit":"€","tips":["Beim Flying-Probe gibt es keine Adapterkosten.","Gesamt = Stückzahl × Kosten je Stück.","300 × 4 €."],"steps":["Gesamt FP = n × Kosten je Stück","Gesamt FP = 300 × 4,00 €","Gesamt FP = 1200 €"],"expl":"Flying-Probe kostet nur je Stück, darum ist es bei Mustern und kleinen Mengen oft die günstigste Wahl."},{"id":"ems17","cat":"Prüfen","title":"Ab wann lohnt ICT?","level":3,"kind":"num","text":"Ein ICT-Adapter kostet 9000 €, der ICT-Test danach 0,20 € je Stück. Flying-Probe kostet 3,20 € je Stück ohne Adapter. Ab welcher Stückzahl sind beide Verfahren gleich teuer?","answer":3000,"tol":0.002,"unit":"Stück","tips":["Gleichstand: n = Adapterpreis / (FP je Stück − ICT je Stück).","Erst die Differenz je Stück ausrechnen.","3,20 € − 0,20 € = 3,00 €."],"steps":["Differenz je Stück = 3,20 € − 0,20 € = 3,00 €","n = 9000 € / 3,00 €","n = 3000 Stück"],"expl":"Unter dem Gleichstand ist Flying-Probe günstiger, darüber lohnt sich der ICT-Adapter."},{"id":"ems18","cat":"Prüfen","title":"Boundary-Scan nutzen","level":2,"kind":"mc","text":"Auf einer dicht bestückten Baugruppe gibt es zwischen zwei großen digitalen Chips viele Verbindungen ohne Prüfpunkte. Wie lassen sie sich trotzdem elektrisch prüfen?","choices":["Mit Boundary-Scan über die eingebaute Testschnittstelle der Chips","Nur durch genaues Hinsehen mit der Lupe","Mit der SPI vor dem Bestücken","Gar nicht, ohne Prüfpunkt ist keine Prüfung möglich"],"correct":0,"tips":["Manche Chips haben eine eigene Testlogik eingebaut.","Diese Schnittstelle kann Pins setzen und lesen.","Boundary heißt Rand: Geprüft wird am Rand des Chips, an seinen Pins."],"expl":"Boundary-Scan steuert über die Testschnittstelle der Chips deren Pins und prüft so die Verbindungen dazwischen. Sichtprüfung und SPI sehen keine elektrischen Fehler, und es geht auch ohne Prüfpunkt."},{"id":"ems19","cat":"Material und Lager","title":"Der richtige ESD-Beutel","level":1,"kind":"mc","text":"Empfindliche Baugruppen sollen für den Versand verpackt werden. Wie ist ein ESD-Schutzbeutel aufgebaut?","choices":["Innen isolierend, außen leitfähig","Innen ableitfähig, dazu eine schirmende Metallschicht","Innen und außen aus normalem Kunststoff, nur farbig markiert","Innen nass, damit keine Ladung entsteht"],"correct":1,"tips":["Am Bauteil soll sich keine Ladung aufbauen.","Von außen sollen Ladungen nicht hineinwirken.","Innen ableiten, eine Metallschicht im Beutel schirmt ab."],"expl":"Die ableitfähige Innenschicht verhindert, dass sich das Bauteil auflädt, die Metallschicht schirmt Felder und Entladungen von außen ab. Isolierende Innenflächen laden sich auf, und eine Farbe allein schützt nicht."},{"id":"ems20","cat":"Material und Lager","title":"FIFO im Lager","level":1,"kind":"mc","text":"Im Lager liegen zwei Rollen desselben Bauteils: eine kam im März, eine im Juni. Beide sind in Ordnung. Welche Rolle wird zuerst gerüstet?","choices":["Die Rolle aus dem Juni, weil sie frischer ist","Egal, beide sind gleich","Die Rolle aus dem März","Die Rolle, die näher an der Linie liegt"],"correct":2,"tips":["FIFO heißt First In, First Out.","Was zuerst kam, geht zuerst raus.","Welche Rolle kam zuerst?"],"expl":"Nach FIFO wird die ältere Rolle zuerst verbraucht, so altert nichts im Regal. Bequemlichkeit oder Zufall führen dazu, dass alte Rollen liegen bleiben."},{"id":"ems21","cat":"Material und Lager","title":"Restzeit MSL 4","level":2,"kind":"num","text":"Eine Rolle mit Bauteilen der Feuchteklasse MSL 4 wurde aus dem Trockenbeutel genommen. Die Rolle war am Montag 8 Stunden und am Dienstag 16 Stunden offen, bei unter 30 °C und 60 % rF. Wie viele Stunden Bodenlebensdauer bleiben noch?","answer":48,"tol":0.002,"unit":"h","tips":["MSL 4 hat eine Bodenlebensdauer von 72 h.","Die offenen Zeiten werden zusammengezählt.","Restzeit = 72 h − (8 h + 16 h)."],"steps":["Bodenlebensdauer MSL 4 = 72 h","Schon offen: 8 h + 16 h = 24 h","Restzeit = 72 h − 24 h = 48 h"],"expl":"Die offene Zeit zählt zusammen, ist die Bodenlebensdauer verbraucht, muss gebacken werden."},{"id":"ems22","cat":"Material und Lager","title":"Bodenlebensdauer abgelaufen","level":3,"kind":"mc","text":"Beim Rüsten stellst du fest: Eine Rolle MSL 3 war schon über 168 Stunden offen. Was ist der richtige Weg?","choices":["Trotzdem verarbeiten, ein paar Stunden machen nichts.","Die Rolle sperren und die Bauteile nach J-STD-033 backen, danach gilt die Bodenlebensdauer neu.","Die Bauteile kurz mit Druckluft abblasen.","Die Rolle in den Kühlschrank legen und morgen verwenden."],"correct":1,"tips":["Feuchte im Gehäuse kann beim Löten zu Rissen führen.","Die Feuchte muss wieder raus.","Die Norm beschreibt, wie man trocknet."],"expl":"Nach Ablauf der Bodenlebensdauer werden die Bauteile gebacken, damit die Feuchte entweicht. Verarbeiten riskiert gerissene Gehäuse, Druckluft und Kühlschrank entfernen keine Feuchte aus dem Inneren."},{"id":"ems23","cat":"Material und Lager","title":"Lagerreichweite","level":1,"kind":"num","text":"Im Lager liegen 12000 Stück eines Widerstands. Die Linie verbraucht jeden Tag 1500 Stück. Für wie viele Tage reicht der Bestand?","answer":8,"tol":0.002,"unit":"Tage","tips":["Reichweite = Bestand / Verbrauch je Tag.","Teile 12000 durch 1500.","1500 × 8 = ?"],"steps":["Reichweite = Bestand / Verbrauch je Tag","Reichweite = 12000 / 1500","Reichweite = 8 Tage"],"expl":"Die Reichweite zeigt, wann spätestens nachbestellt werden muss, Lieferzeit mitdenken."},{"id":"ems24","cat":"Material und Lager","title":"Wie viele Rollen?","level":2,"kind":"num","text":"Ein Auftrag hat 800 Baugruppen. Auf jeder Baugruppe sitzen 12 gleiche Kondensatoren. Eine Rolle enthält 4000 Kondensatoren. Wie viele Rollen werden gebraucht?","answer":3,"tol":0.002,"unit":"Rollen","tips":["Erst den Gesamtbedarf berechnen.","Bedarf = 800 × 12 = 9600.","Teile durch 4000 und runde immer auf."],"steps":["Bedarf = 800 × 12 = 9600 Stück","9600 / 4000 = 2,4","Aufrunden: 3 Rollen"],"expl":"Rollen werden immer aufgerundet, eine halbe Rolle kann man nicht rüsten."},{"id":"ems25","cat":"Qualität","title":"Norm für Automobil","level":1,"kind":"mc","text":"Ein Kunde aus der Automobilindustrie fragt, nach welcher Qualitätsnorm Tonfunk arbeitet. Welche Norm ist speziell für diese Branche?","choices":["ISO 14001","ISO 13485","IATF 16949","IPC-A-610"],"correct":2,"tips":["Die Norm baut auf ISO 9001 auf.","Die Norm stammt von einer Gruppe der Automobilhersteller.","Die Abkürzung beginnt mit IATF."],"expl":"IATF 16949 ist die Qualitätsnorm der Automobilindustrie. ISO 14001 ist Umwelt, ISO 13485 Medizin, IPC-A-610 beschreibt die Annahme von Baugruppen."},{"id":"ems26","cat":"Qualität","title":"Norm für Medizin","level":1,"kind":"mc","text":"Tonfunk ist nach ISO 13485 zertifiziert. Für welche Branche ist diese Norm wichtig?","choices":["Medizinprodukte","Telekom","Lebensmittel","Bauindustrie"],"correct":0,"tips":["Die Norm verlangt besonders strenge Dokumentation und Risikobetrachtung.","Es geht um Geräte, bei denen Menschen direkt betroffen sind.","Denk an Krankenhäuser und Arztpraxen."],"expl":"ISO 13485 ist das Qualitätsmanagement für Medizinprodukte. Für die anderen Branchen gibt es eigene oder allgemeine Normen."},{"id":"ems27","cat":"Qualität","title":"IPC-A-610 Klasse 3","level":2,"kind":"mc","text":"Eine Baugruppe soll nach IPC-A-610 Klasse 3 gefertigt werden. Was bedeutet das?","choices":["Allgemeine Elektronik, kleine Fehler im Aussehen sind egal.","Die Baugruppe darf drei Fehler haben.","Klasse 3 ist die mildeste Klasse für Spielzeug.","Hohe Zuverlässigkeit, ein Ausfall darf nicht passieren, die Grenzen sind am strengsten."],"correct":3,"tips":["Es gibt die Klassen 1, 2 und 3.","Je höher die Klasse, desto strenger.","Denk an lebenserhaltende Medizintechnik."],"expl":"Klasse 3 steht für hohe Zuverlässigkeit mit den strengsten Annahmegrenzen. Klasse 1 ist allgemeine Elektronik, die Zahl hat nichts mit erlaubten Fehlern zu tun."},{"id":"ems28","cat":"Qualität","title":"Zehnerregel einfach","level":2,"kind":"num","text":"Ein falsch geliefertes Bauteil würde im Wareneingang 0,10 € kosten. Nach der Zehnerregel wird der Fehler je Stufe etwa zehnmal teurer: Wareneingang, Fertigung, Endprüfung, Kunde. Was kostet derselbe Fehler, wenn er erst in der Endprüfung auffällt?","answer":10,"tol":0.002,"unit":"€","tips":["Zähle die Stufen vom Wareneingang bis zur Endprüfung.","Wareneingang zu Fertigung: × 10, Fertigung zu Endprüfung: × 10.","0,10 € × 10 × 10."],"steps":["Fertigung: 0,10 € × 10 = 1 €","Endprüfung: 1 € × 10 = 10 €","Kosten = 10 €"],"expl":"Jede Stufe später kostet etwa das Zehnfache, darum wird so früh wie möglich geprüft."},{"id":"ems29","cat":"Qualität","title":"Mehrkosten beim Kunden","level":3,"kind":"num","text":"20 fehlerhafte Bauteile rutschen durch und fallen erst beim Kunden auf. Im Wareneingang hätte jeder Fehler 0,10 € gekostet, beim Kunden kostet er nach der Zehnerregel 100 €. Wie hoch sind die Mehrkosten insgesamt gegenüber dem Finden im Wareneingang?","answer":1998,"tol":0.002,"unit":"€","tips":["Rechne beide Fälle für alle 20 Fehler aus.","Wareneingang: 20 × 0,10 €, Kunde: 20 × 100 €.","Mehrkosten = Kosten beim Kunden − Kosten im Wareneingang."],"steps":["Wareneingang: 20 × 0,10 € = 2 €","Kunde: 20 × 100 € = 2000 €","Mehrkosten = 2000 € − 2 € = 1998 €"],"expl":"Ein Fehler, der beim Kunden landet, kostet ein Vielfaches und dazu noch Vertrauen."},{"id":"ems30","cat":"Qualität","title":"Wann FMEA?","level":2,"kind":"mc","text":"Wann bringt eine FMEA den größten Nutzen?","choices":["Nachdem der Kunde reklamiert hat","Einmal im Jahr zur Inventur","Wenn die Serie schon ein Jahr läuft","In der Planung, bevor gefertigt wird"],"correct":3,"tips":["FMEA heißt Fehlermöglichkeits- und Einflussanalyse.","Möglichkeit heißt: Der Fehler ist noch nicht passiert.","Vorbeugen ist billiger als Nacharbeiten."],"expl":"Die FMEA sucht mögliche Fehler vorab, damit Maßnahmen schon vor der Fertigung greifen. Nach einer Reklamation ist 8D das Werkzeug, die Inventur hat damit nichts zu tun."},{"id":"ems31","cat":"Daten und Rückverfolgung","title":"Barcode auf jeder Platine","level":1,"kind":"mc","text":"Jede Leiterplatte bekommt gleich am Anfang der Linie einen eigenen Code. Wozu?","choices":["Damit jede Station weiß, welche Baugruppe vor ihr liegt, und alle Daten ihr zugeordnet werden","Nur damit die Platine schöner aussieht","Damit der Reflow-Ofen die Temperatur abliest","Damit man die Stückliste nicht mehr braucht"],"correct":0,"tips":["Der Code ist für jede Platine anders.","Jede Station liest ihn ein.","Denk an Rückverfolgung."],"expl":"Der eindeutige Code verbindet jede Baugruppe mit ihren Daten an jeder Station. Aussehen, Ofensteuerung und Stückliste haben damit nichts zu tun."},{"id":"ems32","cat":"Daten und Rückverfolgung","title":"Was steht in der BOM?","level":1,"kind":"mc","text":"Was steht in einer Stückliste (BOM) für eine Baugruppe?","choices":["Die Arbeitszeiten der Mitarbeiter","Die Messwerte aus dem ICT","Alle Bauteile mit Teilenummer, Menge und Bestückposition","Die Rechnungsadresse des Kunden"],"correct":2,"tips":["BOM heißt Bill of Materials.","Material heißt hier: Bauteile.","Aus ihr bestellt der Einkauf."],"expl":"Die BOM listet jedes Bauteil mit Nummer, Menge und Position. Messwerte stehen in den Prüfdaten, Adressen und Arbeitszeiten in anderen Systemen."},{"id":"ems33","cat":"Daten und Rückverfolgung","title":"Aufgabe des MES","level":2,"kind":"mc","text":"Eine Baugruppe hat den ICT nicht bestanden. Ein Kollege will sie trotzdem in die Montage geben. Das MES lässt den Scan nicht zu. Warum?","choices":["Das MES ist kaputt und muss neu gestartet werden.","Das MES speichert jeden Schritt und sperrt Teile, denen ein bestandener Prüfschritt fehlt.","Das MES lässt grundsätzlich nur Teile vom Montag durch.","Das MES erkennt den Kollegen nicht."],"correct":1,"tips":["MES heißt Manufacturing Execution System.","Es kennt den Prüfstatus jeder Seriennummer.","Ungeprüfte oder schlechte Teile sollen nicht weiterlaufen."],"expl":"Das MES prüft die Reihenfolge und den Status jedes Teils und sperrt fehlerhafte Baugruppen. Das ist eine gewollte Schutzfunktion, kein Defekt."},{"id":"ems34","cat":"Daten und Rückverfolgung","title":"Fehlerhaftes Bauteillos","level":3,"kind":"mc","text":"Ein Bauteilhersteller meldet: Ein bestimmtes Los eines Kondensators ist fehlerhaft. Welchen Vorteil hat die Rückverfolgung bis zum einzelnen Gerät?","choices":["Man muss alle jemals gebauten Geräte zurückrufen.","Man kann nichts tun, weil die Geräte schon ausgeliefert sind.","Man findet genau die Geräte, in denen dieses Los verbaut ist, und muss nur diese prüfen.","Man tauscht vorsichtshalber den Lieferanten."],"correct":2,"tips":["Beim Rüsten wird die Losnummer jeder Rolle gescannt.","Die Datenbank verbindet Los und Seriennummer.","Gesucht ist die kleinste betroffene Menge."],"expl":"Durch die Verknüpfung von Los und Seriennummer ist die betroffene Menge genau bekannt. Ein Rückruf aller Geräte wäre teuer und unnötig, ein Lieferantenwechsel löst das aktuelle Problem nicht."},{"id":"ems35","cat":"Daten und Rückverfolgung","title":"Daten zur Seriennummer","level":2,"kind":"mc","text":"Welche Daten werden sinnvoll zur Seriennummer eines Geräts gespeichert? Wähle alle richtigen.","choices":["Losnummern der verbauten Bauteile","Ergebnisse von AOI, ICT und Funktionstest","Privatadresse des späteren Endnutzers","Fertigungsdatum und Linie"],"correct":[0,1,3],"tips":["Es geht um Daten aus der Fertigung.","Was braucht man bei einer Reklamation?","Daten über Privatpersonen gehören nicht in die Fertigungsdaten."],"expl":"Bauteillose, Prüfergebnisse, Datum und Linie erklären, wie das Gerät entstanden ist. Die Adresse eines Endnutzers kennt der Fertiger nicht und braucht sie auch nicht."},{"id":"ems36","cat":"Daten und Rückverfolgung","title":"Rüstkontrolle per Scan","level":2,"kind":"mc","text":"Beim Rüsten scannst du erst den Feederplatz und dann die Rolle. Was verhindert dieser doppelte Scan vor allem?","choices":["Dass eine falsche Rolle auf einem Platz steckt und falsche Bauteile bestückt werden","Dass die Rolle zu schnell leer wird","Dass die Lotpaste austrocknet","Dass die Linie zu langsam läuft"],"correct":0,"tips":["Die Software vergleicht beide Scans mit dem Rüstplan.","Was passiert, wenn zwei Rollen vertauscht sind?","Es geht um das richtige Bauteil am richtigen Platz."],"expl":"Der Abgleich von Platz und Rolle mit dem Rüstplan verhindert vertauschte Bauteile. Verbrauch, Paste und Tempo werden dadurch nicht beeinflusst."},{"id":"ems37","cat":"Montage und Gehäuse","title":"Überwachter Schrauber","level":1,"kind":"mc","text":"In der Montage arbeiten überwachte Drehmomentschrauber. Was ist ihr Vorteil?","choices":["Schnell schrauben, egal wie fest.","Jede Schraube mit dem richtigen Drehmoment anziehen und den Wert speichern.","Ohne Schrauben auskommen.","Die Endprüfung ersetzen."],"correct":1,"tips":["Zu locker und zu fest sind beides Fehler.","Überwacht heißt: Es wird gemessen.","Gemessene Werte gehen in die Rückverfolgung."],"expl":"Der Schrauber prüft und dokumentiert jedes Anzugsmoment. Tempo allein ist kein Qualitätsmerkmal, und die Endprüfung bleibt trotzdem nötig."},{"id":"ems38","cat":"Montage und Gehäuse","title":"Drehmoment ausrechnen","level":1,"kind":"num","text":"Du ziehst eine Schraube mit einem Schlüssel an. Deine Hand drückt mit 50 N, 0,2 m von der Schraubenmitte entfernt. Wie groß ist das Drehmoment?","answer":10,"tol":0.002,"unit":"Nm","tips":["M = F × r.","F = 50 N, r = 0,2 m.","50 × 0,2 = ?"],"steps":["M = F × r","M = 50 N × 0,2 m","M = 10 Nm"],"expl":"Drehmoment ist Kraft mal Hebelarm, ein längerer Hebel braucht weniger Kraft."},{"id":"ems39","cat":"Montage und Gehäuse","title":"Drehmoment mit cm","level":2,"kind":"num","text":"Eine Vorrichtung dreht eine Schraube über einen Hebel von 15 cm Länge. Am Hebelende wirkt eine Kraft von 4 N. Welches Drehmoment entsteht in Nm?","answer":0.6,"tol":0.002,"unit":"Nm","tips":["Erst die Länge in Meter umrechnen.","15 cm = 0,15 m.","M = 4 N × 0,15 m."],"steps":["r = 15 cm = 0,15 m","M = 4 N × 0,15 m","M = 0,6 Nm"],"expl":"Für Nm muss der Hebelarm in Metern stehen, sonst ist das Ergebnis hundertmal zu groß."},{"id":"ems40","cat":"Montage und Gehäuse","title":"Einpressen überwachen","level":2,"kind":"mc","text":"Ein Steckverbinder wird eingepresst. Die Presse zeichnet zu jedem Pin eine Weg-Kraft-Kurve auf. Bei einem Pin steigt die Kraft viel zu früh steil an. Was ist wahrscheinlich?","choices":["Alles in Ordnung, hohe Kraft ist immer gut.","Der Pin ist zu kurz geliefert worden und deshalb gut.","Die Lötstelle ist zu heiß geworden.","Der Pin sitzt schief oder ist verbogen, das Teil wird aussortiert und geprüft."],"correct":3,"tips":["Beim Einpressen wird nicht gelötet.","Eine normale Kurve hat eine bekannte Form.","Früh hohe Kraft heißt: Der Pin stößt irgendwo an."],"expl":"Weicht die Kurve ab, stimmt meist etwas mit Pin oder Bohrung nicht, zum Beispiel ein verbogener Pin. Hohe Kraft ist nicht automatisch gut, und beim Einpressen gibt es keine Lötstelle."},{"id":"ems41","cat":"Montage und Gehäuse","title":"Bohrbild passt knapp","level":3,"kind":"mc","text":"Bei manchen Geräten lassen sich die Schrauben nur schwer eindrehen, weil die Löcher der Leiterplatte und die Dome im Gehäuse nicht genau übereinander liegen. Alle Teile sind innerhalb ihrer Toleranz. Was ist konstruktiv sinnvoll?","choices":["Die Schrauben mit mehr Kraft eindrehen","Die Toleranzkette durchrechnen und in der Leiterplatte etwas Spiel vorsehen, zum Beispiel eine größere Bohrung","Jedes Gehäuse einzeln von Hand nachbohren","Die Leiterplatte festkleben statt schrauben"],"correct":1,"tips":["Alle Teile sind in Ordnung, nur ihre Toleranzen addieren sich.","Die Lösung gehört in die Konstruktion, nicht in die Montage.","Etwas Spiel gleicht die Toleranzen aus."],"expl":"Wenn sich Toleranzen ungünstig addieren, hilft nur eine Konstruktion mit genug Spiel. Mehr Kraft beschädigt Teile, Nacharbeit von Hand kostet viel, Kleben ändert die Funktion und die Reparierbarkeit."},{"id":"ems42","cat":"Montage und Gehäuse","title":"Warum Laserbeschriftung?","level":2,"kind":"mc","text":"Ein Kunde will Seriennummer und Code auf jedem Gehäuse. Warum wird lasergraviert statt ein Etikett geklebt?","choices":["Weil Etiketten verboten sind","Weil der Laser die Elektronik prüft","Weil die Schrift dauerhaft ist, nicht abfallen kann und jedes Gerät seine eigene Nummer bekommt","Weil Laserbeschriftung das Gehäuse stabiler macht"],"correct":2,"tips":["Etiketten können sich ablösen.","Der Laser verändert die Oberfläche selbst.","Denk an Rückverfolgung über viele Jahre."],"expl":"Die Lasergravur ist dauerhaft und kann für jedes Gerät individuell sein. Etiketten sind nicht verboten, und der Laser prüft weder die Elektronik noch macht er das Gehäuse fester."},{"id":"ems43","cat":"Kunde und Kosten","title":"Last Time Buy","level":1,"kind":"mc","text":"Ein Bauteilhersteller schickt eine EOL-Meldung für einen Chip, der in einem Kundenprodukt steckt. Was ist ein Last Time Buy?","choices":["Die letzte Möglichkeit, das Bauteil vor dem Produktionsende zu bestellen","Ein Rabatt für Stammkunden","Die erste Bestellung eines neuen Bauteils","Eine Rücknahme alter Bauteile"],"correct":0,"tips":["EOL heißt End of Life.","Last heißt letzte.","Nach dem Stichtag wird das Bauteil nicht mehr hergestellt."],"expl":"Der Last Time Buy ist die letzte Bestellung vor dem Ende der Herstellung. Danach braucht man Restbestand oder Ersatz. Mit Rabatt, Neueinführung oder Rücknahme hat er nichts zu tun."},{"id":"ems44","cat":"Kunde und Kosten","title":"Allokation","level":1,"kind":"mc","text":"Der Einkauf meldet, ein Mikrocontroller ist in Allokation. Was bedeutet das?","choices":["Das Bauteil ist abgekündigt und kommt nie wieder.","Das Bauteil ist knapp, die Hersteller teilen Mengen zu, die Lieferzeit wird lang.","Das Bauteil ist besonders günstig zu haben.","Das Bauteil liegt schon im Lager."],"correct":1,"tips":["Allokation kommt von zuteilen.","Es gibt mehr Nachfrage als Ware.","Das Bauteil wird weiter hergestellt, aber nicht genug."],"expl":"Bei Allokation ist ein Bauteil knapp und wird zugeteilt, die Lieferzeiten steigen. Abgekündigt ist EOL, günstig oder vorrätig ist das Gegenteil von knapp."},{"id":"ems45","cat":"Kunde und Kosten","title":"Kosten je Baugruppe","level":3,"kind":"num","text":"Kalkuliere die Kosten je Baugruppe: Material 12,00 €, 200 Bestückpunkte zu je 0,02 €, 10 THT-Lötstellen zu je 0,05 €, 2 Minuten Prüfzeit bei 1,50 € je Minute, Rüstkosten 500 € bei einer Losgröße von 250 Stück.","answer":21.5,"tol":0.002,"unit":"€","tips":["Rechne jeden Baustein einzeln aus und zähle dann zusammen.","Bestücken 200 × 0,02 €, THT 10 × 0,05 €, Prüfen 2 × 1,50 €.","Rüstkosten je Stück = 500 € / 250."],"steps":["Bestücken 200 × 0,02 € = 4,00 €; THT 10 × 0,05 € = 0,50 €; Prüfen 2 × 1,50 € = 3,00 €","Rüsten 500 € / 250 = 2,00 €","Kosten = 12,00 + 4,00 + 0,50 + 3,00 + 2,00 = 21,50 €"],"expl":"Die Kalkulation besteht aus Material, Bestückpunkten, Lötstellen, Prüfzeit und anteiligen Rüstkosten."},{"id":"ems46","cat":"Kunde und Kosten","title":"Angebotspreis","level":2,"kind":"num","text":"Eine Baugruppe kostet in der Kalkulation 40,00 €. Der Zuschlag beträgt 15 %. Wie hoch ist der Angebotspreis je Baugruppe?","answer":46,"tol":0.002,"unit":"€","tips":["Angebot = Kosten × (1 + Zuschlag).","15 % = 0,15.","40 € × 1,15."],"steps":["Angebot = 40,00 € × (1 + 0,15)","Angebot = 40,00 € × 1,15","Angebot = 46,00 €"],"expl":"Der Zuschlag deckt Gemeinkosten, Risiko und Gewinn und wird auf die Kosten aufgeschlagen."},{"id":"ems47","cat":"Kunde und Kosten","title":"Rüstkosten und Losgröße","level":2,"kind":"num","text":"Das Rüsten eines Auftrags kostet 600 €. Der Kunde fragt, um wie viel Euro jedes Stück günstiger wird, wenn er 600 statt 50 Stück je Los bestellt. Rechne nur mit den Rüstkosten.","answer":11,"tol":0.002,"unit":"€","tips":["Rüstkosten je Stück = Rüstkosten / Losgröße.","Rechne beide Losgrößen aus.","600 € / 50 und 600 € / 600."],"steps":["Los 50: 600 € / 50 = 12 € je Stück","Los 600: 600 € / 600 = 1 € je Stück","Ersparnis = 12 € − 1 € = 11 € je Stück"],"expl":"Größere Lose verteilen die Rüstkosten auf mehr Teile, binden aber mehr Geld im Lager."},{"id":"ems48","cat":"Kunde und Kosten","title":"Mehr als bestellt","level":3,"kind":"mc","text":"Bei der Datenprüfung für einen Bestückauftrag fällt dir auf: Ein Bauteil der Stückliste hat bereits eine EOL-Meldung. Der Kunde hat nur die Bestückung angefragt. Was ist das beste Vorgehen?","choices":["Nichts sagen, der Kunde hat nur Bestückung bestellt.","Das Bauteil ohne Rücksprache durch ein anderes ersetzen.","Den Auftrag ablehnen.","Den Kunden früh informieren und eine Lösung vorschlagen, zum Beispiel Last Time Buy oder ein geprüftes Ersatzbauteil."],"correct":3,"tips":["Denk an die Werte Kommunikation und Partnerschaft.","Ein Bauteiltausch ohne Freigabe ändert das Produkt des Kunden.","Es gibt immer eine Lösung, gemeinsam mit dem Kunden."],"expl":"Der Kunde bekommt mehr als erwartet, wenn ein Risiko früh gemeldet und eine Lösung angeboten wird. Schweigen schadet später, ein Tausch ohne Freigabe ist nicht erlaubt, und Ablehnen hilft niemandem."}],"help":[{"h":"8D","t":"Methode in acht Schritten, um eine Reklamation zu bearbeiten. Die Methode reicht von der Sofortmaßnahme über die Ursache bis zur dauerhaften Abstellung."},{"h":"Allokation","t":"Zuteilung knapper Bauteile durch die Hersteller. Die Lieferzeiten werden lang, und man bekommt oft weniger als bestellt."},{"h":"AOI","t":"Automatische optische Inspektion. Kameras vergleichen jede Baugruppe mit dem Sollbild und finden fehlende, falsche oder schlecht gelötete Bauteile."},{"h":"BOM","t":"Bill of Materials, deutsch Stückliste. Die BOM listet jedes Bauteil mit Teilenummer, Menge und Bestückposition."},{"h":"Boundary-Scan","t":"Prüfverfahren über eine eingebaute Testschnittstelle digitaler Chips. Damit prüft man Verbindungen auch dort, wo keine Prüfnadel hinkommt."},{"h":"CAQ","t":"Computer Aided Quality, Software für das Qualitätsmanagement. Das CAQ verwaltet zum Beispiel FMEA, Prüfpläne, Messwerte und Reklamationen."},{"h":"Dam & Fill","t":"Schutzverfahren: Erst wird ein Damm aus dickflüssigem Material gezogen, dann wird die Fläche darin mit dünnflüssigem Material gefüllt. So wird nur ein bestimmter Bereich vergossen."},{"h":"EMS","t":"Electronic Manufacturing Services. Ein EMS-Dienstleister fertigt Elektronik im Auftrag anderer Firmen."},{"h":"EOL","t":"End of Life. Meldung des Herstellers, dass ein Bauteil nicht mehr hergestellt wird."},{"h":"EPA","t":"ESD Protected Area, ein vor elektrostatischer Entladung geschützter Bereich nach DIN EN 61340-5-1. Dort sind Boden, Tische, Kleidung und Personen geerdet oder ableitfähig."},{"h":"ESD","t":"Electrostatic Discharge, elektrostatische Entladung. Schon ein Funke, den du nicht spürst, kann einen Chip beschädigen."},{"h":"Feeder","t":"Zuführung an der Bestückmaschine. Der Feeder schiebt den Gurt mit den Bauteilen Tasche für Tasche vor."},{"h":"FIFO","t":"First In, First Out. Was zuerst ins Lager kam, wird zuerst verbraucht."},{"h":"First Pass Yield","t":"Anteil der Teile, die ohne Nacharbeit beim ersten Durchlauf gut sind. Der FPY einer Linie ist das Produkt der Ausbeuten aller Stufen."},{"h":"Flying-Probe","t":"Elektrischer Test mit wenigen beweglichen Nadeln, die die Prüfpunkte nacheinander anfahren. Kein Adapter nötig, gut für Muster, kleine und mittlere Stückzahlen."},{"h":"FMEA","t":"Fehlermöglichkeits- und Einflussanalyse. Vor der Fertigung werden mögliche Fehler bewertet und Maßnahmen gegen die größten Risiken festgelegt."},{"h":"Funktionstest","t":"Prüfung, ob eine Baugruppe oder ein Gerät die geforderte Funktion erfüllt. Die Prüfvorschrift kommt meist vom Kunden."},{"h":"IATF 16949","t":"Qualitätsnorm der Automobilindustrie. Die Norm baut auf ISO 9001 auf und stellt zusätzliche Anforderungen."},{"h":"ICT","t":"In-Circuit-Test. Ein Nadeladapter kontaktiert viele Prüfpunkte gleichzeitig und misst Bauteile und Verbindungen, schnell bei großen Stückzahlen."},{"h":"IPC-A-610","t":"Weltweit genutzter Standard, der mit Bildern zeigt, wann eine bestückte Baugruppe annehmbar ist. Es gibt die Klassen 1, 2 und 3, Klasse 3 ist am strengsten."},{"h":"ISO 13485","t":"Qualitätsnorm für Medizinprodukte. Die Norm fordert besonders gründliche Dokumentation und Risikobetrachtung."},{"h":"Last Time Buy","t":"Letzte Bestellmöglichkeit für ein Bauteil, bevor es nach einer EOL-Meldung nicht mehr hergestellt wird."},{"h":"MES","t":"Manufacturing Execution System. Software, die Aufträge steuert, jeden Fertigungsschritt speichert und fehlerhafte Teile sperren kann."},{"h":"MSL","t":"Moisture Sensitivity Level, Feuchteklasse eines Bauteils nach J-STD-020. Die Klasse bestimmt nach J-STD-033, wie lange das Bauteil außerhalb der Trockenverpackung liegen darf."},{"h":"NPI","t":"New Product Introduction, Neuprodukt-Einführung. Daten prüfen, Muster bauen und Programme erstellen, bis die Serie sicher läuft."},{"h":"Obsoleszenz","t":"Ein Bauteil wird nicht mehr hergestellt. Obsoleszenz-Management erkennt das früh und sucht Lösungen."},{"h":"OEM","t":"Original Equipment Manufacturer. Hersteller, der ein Produkt unter seiner eigenen Marke verkauft."},{"h":"Reflow","t":"Lötverfahren für SMD-Bauteile. Im Ofen schmilzt die Lotpaste und verlötet alle Bauteile auf einmal."},{"h":"Röntgen (AXI)","t":"Automatische Röntgeninspektion. Das Röntgenbild zeigt verdeckte Lötstellen, etwa unter BGA und QFN."},{"h":"Rückverfolgung","t":"Man kann für jedes Gerät nachweisen, welche Bauteillose verbaut wurden und welche Prüfungen es bestanden hat. Umgekehrt findet man zu einem Los alle betroffenen Geräte."},{"h":"Schutzlack","t":"Dünne Schicht auf der Baugruppe gegen Feuchte, Staub und Betauung. Wird gesprüht, getaucht, geschleppt oder gepinselt."},{"h":"Selektivlöten","t":"THT-Lötverfahren mit einer kleinen Lotwelle, der Mini-Welle. Es lötet nur ausgewählte Stellen."},{"h":"SMT","t":"Surface Mount Technology, Oberflächenmontage. Die Bauteile sitzen direkt auf der Oberfläche der Leiterplatte."},{"h":"SPI","t":"Solder Paste Inspection. Misst nach dem Druck jedes Lotpastendepot in 3D, bevor bestückt wird."},{"h":"Stickstoff beim Löten","t":"Stickstoff verdrängt den Sauerstoff im Ofen oder an der Welle. Das Lot oxidiert weniger und benetzt besser."},{"h":"THT","t":"Through Hole Technology, Durchsteckmontage. Bauteile mit Drähten stecken durch Bohrungen der Leiterplatte."},{"h":"Underfill","t":"Füllmaterial, das unter große Bauteile wie BGA fließt und aushärtet. Es stärkt die Lötstellen gegen Biegen und Vibration."},{"h":"Verguss","t":"Die Baugruppe wird ganz oder teilweise in Epoxid, PU oder Silikon eingegossen. Das schützt vor Feuchte, Vibration und Berührung."},{"h":"Voids","t":"Hohlräume oder Gasblasen in einer Lötstelle. Zu große Voids schwächen die Verbindung und die Wärmeableitung, man sieht sie im Röntgenbild."},{"h":"Wellenlöten","t":"THT-Lötverfahren, bei dem die Unterseite der Leiterplatte über eine Welle aus flüssigem Lot fährt."}]};
  root.EMS_DATA = D;
  if (typeof module !== 'undefined' && module.exports) module.exports = D;
})(typeof window !== 'undefined' ? window : globalThis);
